-- Required Buried Sea encounter templates; not deployed until whole-batch activation.
-- New reserved NPC IDs only. Existing NPCs, loot tables and player data stay intact.
-- Combat numbers are labelled configurable defaults in data/encounter-profiles.json.
-- The troll receives its single original bill as native loot at leased scene spawn.
SET NAMES utf8mb4;
SET SESSION check_constraint_checks=1;
DROP TEMPORARY TABLE IF EXISTS `_tbs_encounters`;
CREATE TEMPORARY TABLE `_tbs_encounters` LIKE npc_types;
