 AND (SELECT COUNT(*) FROM npc_types WHERE id=422074 AND name='Silverlip_Slim')=1
 AND NOT EXISTS(SELECT 1 FROM npc_types a JOIN `_tbs_encounters` e ON a.id=e.id WHERE NOT (a.`id`<=>e.`id` AND a.`name`<=>e.`name` AND a.`lastname`<=>e.`lastname` AND a.`level`<=>e.`level` AND a.`race`<=>e.`race` AND a.`class`<=>e.`class` AND a.`bodytype`<=>e.`bodytype` AND a.`hp`<=>e.`hp` AND a.`mana`<=>e.`mana` AND a.`gender`<=>e.`gender` AND a.`texture`<=>e.`texture` AND a.`helmtexture`<=>e.`helmtexture` AND a.`herosforgemodel`<=>e.`herosforgemodel` AND a.`size`<=>e.`size` AND a.`hp_regen_rate`<=>e.`hp_regen_rate` AND a.`hp_regen_per_second`<=>e.`hp_regen_per_second` AND a.`mana_regen_rate`<=>e.`mana_regen_rate` AND a.`loottable_id`<=>e.`loottable_id` AND a.`merchant_id`<=>e.`merchant_id` AND a.`greed`<=>e.`greed` AND a.`alt_currency_id`<=>e.`alt_currency_id` AND a.`npc_spells_id`<=>e.`npc_spells_id` AND a.`npc_spells_effects_id`<=>e.`npc_spells_effects_id` AND a.`npc_faction_id`<=>e.`npc_faction_id` AND a.`adventure_template_id`<=>e.`adventure_template_id` AND a.`trap_template`<=>e.`trap_template` AND a.`mindmg`<=>e.`mindmg` AND a.`maxdmg`<=>e.`maxdmg` AND a.`attack_count`<=>e.`attack_count` AND a.`npcspecialattks`<=>e.`npcspecialattks` AND a.`special_abilities`<=>e.`special_abilities` AND a.`aggroradius`<=>e.`aggroradius` AND a.`assistradius`<=>e.`assistradius` AND a.`face`<=>e.`face` AND a.`luclin_hairstyle`<=>e.`luclin_hairstyle` AND a.`luclin_haircolor`<=>e.`luclin_haircolor` AND a.`luclin_eyecolor`<=>e.`luclin_eyecolor` AND a.`luclin_eyecolor2`<=>e.`luclin_eyecolor2` AND a.`luclin_beardcolor`<=>e.`luclin_beardcolor` AND a.`luclin_beard`<=>e.`luclin_beard` AND a.`drakkin_heritage`<=>e.`drakkin_heritage` AND a.`drakkin_tattoo`<=>e.`drakkin_tattoo` AND a.`drakkin_details`<=>e.`drakkin_details` AND a.`armortint_id`<=>e.`armortint_id` AND a.`armortint_red`<=>e.`armortint_red` AND a.`armortint_green`<=>e.`armortint_green` AND a.`armortint_blue`<=>e.`armortint_blue` AND a.`d_melee_texture1`<=>e.`d_melee_texture1` AND a.`d_melee_texture2`<=>e.`d_melee_texture2` AND